/**
 *
 * TabsPrev is the previous navigation button for scrollable tabs.
 *
 * [Live Demo](https://www.primereact.org/tabs/)
 *
 * @module TabsPrev
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TabsRootInstance } from './TabsRoot.types';
/**
 * Defines passthrough(pt) options type in TabsPrev component.
 */
export type TabsPrevPassThroughType<E> = PassThroughType<TabsPrevInstance, E>;
/**
 * Defines passthrough(pt) options of TabsPrev component.
 */
export interface TabsPrevPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TabsPrevPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in TabsPrev component.
 */
export interface TabsPrevProps extends BaseComponentProps<TabsPrevInstance, unknown, TabsPrevPassThrough> {
    /**
     * Aria label for the previous button.
     */
    ariaLabel?: string;
    /**
     * When enabled, the button is unmounted from the DOM when it is not needed.
     * @default false
     */
    lazy?: boolean;
}
/**
 * Defines valid state in TabsPrev component.
 */
export interface TabsPrevState {
}
/**
 * Defines the methods and properties exposed by TabsPrev component.
 */
export interface TabsPrevExposes {
    /**
     * The Tabs component instance.
     */
    tabs: TabsRootInstance | undefined | null;
}
/**
 * Instance of TabsPrev component.
 */
export type TabsPrevInstance = ComponentInstance<TabsPrevProps, TabsPrevState, TabsPrevExposes>;
